/**
 * JSON Schemas of the exported documents, generated by Zod from the final
 * document schemas at export time.
 *
 * The schemas are built on demand so the package always carries the contract
 * that the generator enforces, with no second definition to keep in sync.
 */
import { z } from "astro/zod";

import { categorySchema } from "./category";
import { productSchema } from "./product";
import { siteMetaSchema } from "./site";

/** JSON Schema produced by Zod for one exported document. */
export type DocumentJsonSchema = Record<string, unknown>;

/**
 * Adds the `$schema` property that every generated document carries, so a
 * document with its reference still validates against its own schema.
 * @param schema Schema produced by Zod.
 * @returns The schema with the reference property declared as required.
 */
function withSchemaReference(schema: DocumentJsonSchema): DocumentJsonSchema {
  const properties = schema.properties as Record<string, unknown>;
  properties.$schema = { type: "string" };
  const required = schema.required as string[];
  required.unshift("$schema");
  return schema;
}

/**
 * JSON Schema of the exported site document.
 * @returns The schema produced by Zod, with the document reference.
 */
export function siteJsonSchema(): DocumentJsonSchema {
  return withSchemaReference(
    z.toJSONSchema(siteMetaSchema) as DocumentJsonSchema,
  );
}

/**
 * JSON Schema of the exported product document.
 * @returns The schema produced by Zod, with the document reference.
 */
export function productJsonSchema(): DocumentJsonSchema {
  return withSchemaReference(
    z.toJSONSchema(productSchema) as DocumentJsonSchema,
  );
}

/**
 * JSON Schema of the exported category document.
 * @returns The schema produced by Zod, with the document reference.
 */
export function categoryJsonSchema(): DocumentJsonSchema {
  return withSchemaReference(
    z.toJSONSchema(categorySchema) as DocumentJsonSchema,
  );
}
